const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateKey(new Date()), parseDate=s=>new Date(s+'T00:00:00'), addDays=(s,n)=>{let d=parseDate(s);d.setDate(d.getDate()+n);return dateKey(d)}, minutes=s=>Number(s.split(':')[0])*60+Number(s.split(':')[1]);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats={Work:['⌘','#e8edde','#7b8f62'],Study:['▤','#ede9df','#a08d66'],Wellness:['♧','#e7eddf','#82946b'],Meeting:['▧','#e8e8f0','#8d89a4'],Personal:['☕','#f1e8de','#b49a7c'],Sleep:['☾','#e5eaf0','#8a9bae'],Office:['▣','#e7eae5','#7e9078'],Custom:['✳','#eee6ea','#a58896']};
let state;try{state=JSON.parse(localStorage.getItem('dayform-v1'))}catch{}let storageFailed=false;
if(!state){state={activities:[],done:{},logs:[],reminders:false,seed:true};const seeds=[['A slow start & morning stretch','Wellness','07:00','07:30'],['Deep work · make something good','Work','09:00','11:00'],['Product team catch-up','Meeting','11:30','12:00'],['Lunch & a little reset','Personal','12:30','13:30'],['Learn something new','Study','14:00','15:30'],['Move your body','Wellness','17:30','18:30'],['Wind down & recharge','Sleep','22:00','07:00']];seeds.forEach((a,i)=>state.activities.push({id:crypto.randomUUID(),title:a[0],category:a[1],date:today(),start:a[2],end:a[3],repeat:'none',link:'',notes:'Sample activity — make this day your own.'}));}
state.done ||= {}; state.logs ||= [];
let view='dashboard',selected=today(),filter='all',charts=[],calendarMonth=parseDate(today());
function save(){try{localStorage.setItem('dayform-v1',JSON.stringify(state));storageFailed=false}catch{storageFailed=true;toast('Storage is full or unavailable. Export a backup to keep your changes.')}$('.local-label').textContent=storageFailed?'Changes not saved':'● All changes saved locally'}
function log(type,message){state.logs.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),type,message});save()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function duration(a){let n=minutes(a.end)-minutes(a.start);return n<=0?n+1440:n}
function occurs(a,date){if(date<a.date)return false;let s=parseDate(a.date),d=parseDate(date);if(a.repeat==='none')return date===a.date;if(a.repeat==='daily')return true;if(a.repeat==='weekly')return s.getDay()===d.getDay();const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();if(a.repeat==='monthly')return d.getDate()===Math.min(s.getDate(),last);return d.getMonth()===s.getMonth()&&d.getDate()===Math.min(s.getDate(),last)}
function events(date){return state.activities.filter(a=>occurs(a,date)).map(a=>({...a,key:a.id+'@'+date,day:date,begin:new Date(date+'T'+a.start),finish:new Date(new Date(date+'T'+a.start).getTime()+duration(a)*60000)})).sort((a,b)=>a.start.localeCompare(b.start))}
function dayAllocation(date){let slots=Array(1440).fill('Unplanned');for(const d of [addDays(date,-1),date])for(const a of events(d)){let base=d===date?0:-1440;let start=base+minutes(a.start);for(let i=Math.max(0,start);i<Math.min(1440,start+duration(a));i++)slots[i]=a.category}let totals={};slots.forEach(c=>totals[c]=(totals[c]||0)+1);return totals}
function hours(n){return Number((n/60).toFixed(1))+'h'}
function fmtTime(t){const [h,m]=t.split(':');return `${Number(h)%12||12}:${m} ${Number(h)<12?'AM':'PM'}`}
function catStyle(c){return `--cat-bg:${cats[c][1]};--cat-color:${cats[c][2]}`}
function activityRow(a){let done=state.done[a.key],locked=Date.now()<a.begin.getTime(),late=!done&&Date.now()>a.finish.getTime();return `<div class="activity-row"><div class="time-label">${fmtTime(a.start).replace(' ','<br>')}</div><article class="activity ${done?'done':locked?'':'next'}" style="${catStyle(a.category)}"><span class="activity-icon">${cats[a.category][0]}</span><div class="activity-info"><div class="activity-title">${esc(a.title)}</div><div class="activity-meta"><span>${fmtTime(a.start)} – ${fmtTime(a.end)}</span><span>· ${hours(duration(a))}</span><span class="tag">${a.category}</span>${a.repeat!=='none'?'<span title="Repeating activity">↻</span>':''}${late?'<span>Overdue</span>':''}${locked?'<span>⌑ Scheduled</span>':''}${a.link?`<a target="_blank" rel="noopener" href="${esc(a.link)}">Join ↗</a>`:''}</div></div><div class="activity-actions"><input type="checkbox" aria-label="Complete ${esc(a.title)}" data-complete="${a.key}" ${done?'checked':''} ${locked?'disabled title="Completion unlocks at the scheduled start"':''}><button class="mini-btn" data-edit="${a.id}" title="Edit or reschedule" aria-label="Reschedule ${esc(a.title)}">↗</button><button class="mini-btn" data-delete="${a.id}" title="Delete activity" aria-label="Delete ${esc(a.title)}">×</button></div></article></div>`}
function header(title,sub,tag='YOUR EVERYDAY, REIMAGINED'){return `<div class="page-heading"><div><span class="heading-tag">${tag}</span><h1>${title}</h1><p>${sub}</p></div><button class="primary" data-add>＋ <span>Add activity</span></button></div>`}
function toolbar(){return `<div class="toolbar"><button class="soft-button" data-shift="-1" aria-label="Previous day">‹</button><input class="date-picker" type="date" id="selected-date" aria-label="Selected date" value="${selected}"><button class="soft-button" data-shift="1" aria-label="Next day">›</button><button class="soft-button" id="today">Today</button><div class="right"><span class="week-pill"><button class="active" data-view="dashboard">Day</button><button data-view="timetable">24 hours</button><button data-view="calendar">Month</button></span></div></div>`}
function stats(){let ev=events(selected),done=ev.filter(a=>state.done[a.key]).length,allocation=dayAllocation(selected),planned=1440-(allocation.Unplanned||0),late=ev.filter(a=>!state.done[a.key]&&Date.now()>a.finish).length;return `<div class="stats">${[['Daily progress','◉',ev.length?Math.round(done/ev.length*100)+'%':'0%',`${done} of ${ev.length} activities complete`],['Planned time','◷',hours(planned)+' <em>/ 24h</em>',`${hours(1440-planned)} of breathing room`],['Activities today','▦',String(ev.length).padStart(2,'0'),'A little structure, a lot of possibility'],['Needs attention','↗',String(late).padStart(2,'0'),late?'Overdue activities to revisit':'You’re right where you need to be']].map((s,i)=>`<div class="stat"><div class="stat-label">${s[0]}<span>${s[1]}</span></div><div class="stat-value">${s[2]}</div><div class="stat-note">${s[3]}</div>${i===0?'<div class="tiny-bars">'+[12,18,15,23,20,29,32].map(h=>`<i style="height:${h}px"></i>`).join('')+'</div>':''}</div>`).join('')}</div>`}
function allocationCard(){let al=dayAllocation(selected);return `<section class="card"><div class="card-head"><div><h2>A little of everything</h2><p>Your 24 hours, in perspective</p></div><span class="muted">◴</span></div><div class="chart-wrap"><canvas id="allocation" aria-label="24-hour time allocation chart" role="img"></canvas><div class="chart-center"><strong>24<span style="font-size:13px">h</span></strong><small>YOUR WHOLE DAY</small></div></div><div class="legend">${Object.entries(al).sort((a,b)=>b[1]-a[1]).map(([c,n])=>`<div class="legend-item"><i style="background:${cats[c]?.[2]||'#e7ebdf'}"></i>${c}<b>${hours(n)}</b></div>`).join('')}</div></section>`}
function upcoming(){let next=[];for(let i=0;i<8;i++)next.push(...events(addDays(today(),i)).filter(a=>a.begin>Date.now()&&!state.done[a.key]));next=next.slice(0,3);return `<section class="card"><div class="card-head"><div><h2>On the horizon <span class="count-badge">UP NEXT</span></h2><p>A gentle heads-up for what’s ahead</p></div></div><div class="upcoming">${next.map(a=>`<div class="upcoming-row" style="${catStyle(a.category)}"><span class="activity-icon">${cats[a.category][0]}</span><div><h3>${esc(a.title)}</h3><small>${a.day===today()?'Today':parseDate(a.day).toLocaleDateString(undefined,{month:'short',day:'numeric'})} · ${fmtTime(a.start)}</small></div><button class="when" data-edit="${a.id}">↗</button></div>`).join('')||'<div class="empty">A clear horizon. Make space for something good.</div>'}</div></section>`}
function dashboard(){let ev=events(selected),filtered=ev.filter(a=>filter==='all'||(filter==='done'?state.done[a.key]:!state.done[a.key]));return header(selected===today()?'A little intention. A better day.':'Make room for your day.','Your plans, your pace. Let’s make today feel good.')+toolbar()+stats()+`<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Your daily flow <span class="count-badge">${ev.length} activities</span></h2><p>${parseDate(selected).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} · One thing at a time</p></div><button class="text-button" data-view="timetable">Full timetable ↗</button></div><div class="schedule-tabs">${[['all','All activities'],['pending','To do'],['done','Completed']].map(([v,t])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${t}</button>`).join('')}</div><div class="timeline">${filtered.map(activityRow).join('')||'<div class="empty">Nothing here yet.<br>Add an activity to give your day a little direction.</div>'}</div><div style="padding:0 22px 20px"><button class="text-button" data-add>＋ Make room for something else</button></div></section><div class="right-stack">${allocationCard()}${upcoming()}<div class="balance-banner"><span>✳</span><div><h3>Rest is part of the plan.</h3><p>A little breathing room goes a long way.<br>You don’t have to fill every hour.</p></div></div></div></div><div class="lower-grid"><section class="card"><div class="card-head"><div><h2>Finding your rhythm</h2><p>Completed activities over the last 7 days</p></div><button class="text-button" data-view="analytics">Explore insights ↗</button></div><div class="bar-chart"><canvas id="week-chart" role="img" aria-label="Completed activities over seven days"></canvas></div></section><section class="card"><div class="card-head"><div><h2>Small steps. Real progress.</h2><p>Your activity check-in, one day at a time</p></div><span>✧</span></div><div class="rhythm">${Array.from({length:14},(_,i)=>{let d=addDays(selected,i-13);return `<i title="${d}" class="${events(d).some(a=>state.done[a.key])?'filled':''}"></i>`}).join('')}</div><p class="insight-text">${state.seed?'Start with a sample day, then make it yours. Edit or remove any activity to build a routine that fits.':'Consistency grows one check-in at a time. Your progress appears here as you complete activities.'}</p></section></div>`}
function calendar(){let start=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1),first=new Date(start);first.setDate(1-((start.getDay()+6)%7));return header('A wider view of your days.','Room for your routines, and the things you look forward to.','THE BIGGER PICTURE')+`<div class="toolbar"><button class="soft-button" id="prev-month">‹</button><h2>${start.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><button class="soft-button" id="next-month">›</button><button class="soft-button" id="month-today">This month</button></div><div class="card calendar-card"><div class="calendar-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<div class="day-heading">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{let d=new Date(first);d.setDate(first.getDate()+i);let key=dateKey(d),ev=events(key);return `<div class="calendar-day ${key===today()?'today':''} ${d.getMonth()!==start.getMonth()?'outside':''}"><button data-day="${key}">${d.getDate()}</button>${ev.slice(0,3).map(a=>`<button class="calendar-event" data-edit="${a.id}">${a.start} ${esc(a.title)}</button>`).join('')}${ev.length>3?`<button class="text-button" data-day="${key}">+ ${ev.length-3} more</button>`:''}</div>`}).join('')}</div></div>`}
function timetable(){let ev=[...events(addDays(selected,-1)).filter(a=>a.finish>parseDate(selected)),...events(selected)];return header('Your day, hour by hour.','A complete 24-hour view. Click an empty hour to make a plan.','A LITTLE STRUCTURE')+toolbar()+`<section class="card"><div class="card-head"><h2>24-hour timetable</h2><span class="muted" style="font-size:10px">Overnight activities included · Local time</span></div>${Array.from({length:24},(_,h)=>{let from=new Date(selected+'T'+String(h).padStart(2,'0')+':00'),to=new Date(from.getTime()+3600000),list=ev.filter(a=>a.begin<to&&a.finish>from);return `<div class="timetable-hour"><span>${String(h).padStart(2,'0')}:00</span><div class="hour-content">${list.length?list.map(a=>`<button data-edit="${a.id}">${cats[a.category][0]} &nbsp; ${esc(a.title)} <span class="muted">· ${a.start}–${a.end}${a.day!==selected?' · from yesterday':''}</span></button>`).join(''):`<button data-hour="${h}" style="background:transparent;border-color:#edf0e7;color:#a7b09e">＋ Open space</button>`}</div></div>`}).join('')}</section>`}
function lastDays(n){return Array.from({length:n},(_,i)=>addDays(selected,i-n+1))}
function analytics(){let days=lastDays(30),ev=days.flatMap(events).filter(a=>a.begin<=Date.now()),missed=days.filter(d=>d<today()&&events(d).length&&!events(d).some(a=>state.done[a.key])).length;let groups=Object.keys(cats).map(c=>{let list=ev.filter(a=>a.category===c),done=list.filter(a=>state.done[a.key]),delays=done.map(a=>Math.max(0,(new Date(state.done[a.key])-a.finish)/60000));return {c,total:list.length,done:done.length,overdue:list.filter(a=>!state.done[a.key]&&a.finish<Date.now()).length,delay:delays.length?Math.round(delays.reduce((a,b)=>a+b,0)/delays.length):0}}).filter(g=>g.total);return header('Understand your everyday.','Real patterns from your activity history. A little awareness goes a long way.','INSIGHTS & ANALYTICS')+toolbar()+stats()+`<div class="analytics-grid"><section class="card"><div class="card-head"><div><h2>Your weekly momentum</h2><p>Completed and scheduled activities · Last 7 days</p></div></div><div class="bar-chart"><canvas id="week-chart"></canvas></div></section>${allocationCard()}<section class="card" style="grid-column:1/-1"><div class="card-head"><div><h2>Where your time finds its rhythm</h2><p>Last 30 days · ${missed} past scheduled days without a completion check-in</p></div></div><div class="table-wrap"><table><thead><tr><th>ACTIVITY CATEGORY</th><th>COMPLETION</th><th>OVERDUE</th><th>AVG. COMPLETION DELAY</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${cats[g.c][0]} &nbsp; ${g.c}</td><td>${g.done}/${g.total} <small>${Math.round(g.done/g.total*100)}% complete</small></td><td>${g.overdue}</td><td>${g.delay} min <small>After scheduled end</small></td></tr>`).join('')||'<tr><td colspan="4">No activity history for this period yet.</td></tr>'}</tbody></table></div></section><section class="card" style="grid-column:1/-1"><div class="card-head"><div><h2>Activities that need a little care</h2><p>Overdue occurrences · Most delayed first</p></div></div><div class="timeline">${ev.filter(a=>!state.done[a.key]&&a.finish<Date.now()).sort((a,b)=>a.finish-b.finish).slice(0,10).map(a=>`<div style="margin-bottom:8px"><small>${a.day} · ${Math.floor((Date.now()-a.finish)/3600000)} hours overdue</small>${activityRow(a)}</div>`).join('')||'<div class="empty">No overdue activities. A little peace of mind.</div>'}</div></section></div>`}
function notifications(){return header('A gentle nudge, thoughtfully kept.','A transparent history of reminders and schedule changes.','NOTIFICATION LOG')+`<div class="balance-banner" style="margin-bottom:22px"><span>♧</span><div><h3>Daily check-in · 8:00 PM local time</h3><p>${state.reminders?'Reminders enabled.':'Reminders are currently off.'} Keep this planner open for browser notifications. Closed-browser reminders are not supported.</p></div><button class="soft-button" id="enable-reminders">${state.reminders?'Disable':'Enable'}</button></div><section class="card"><div class="card-head"><h2>Notification & activity audit</h2><button class="text-button" id="export-log">Export log ↓</button></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>EVENT</th><th>DETAILS</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td>${new Date(l.at).toLocaleString()}</td><td>${esc(l.type)}</td><td>${esc(l.message)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No events yet. Actual reminder attempts and changes will appear here.</td></tr>'}</tbody></table></div></section>`}
function settings(){return header('Make this space your own.','Simple preferences for an intentional everyday.','PREFERENCES')+`<section class="card settings-card"><h2>Your personal space</h2><div class="setting-row"><div><h3>8 PM daily reminder</h3><p>Browser notifications in your local timezone.<br>The planner must be open. Permission is required.</p></div><button class="soft-button" id="enable-reminders">${state.reminders?'Disable':'Enable'}</button></div><div class="setting-row"><div><h3>Keep a copy of your plans</h3><p>Export activities, completion history, and audit events as JSON.<br>Your data is stored in this browser, without cross-device sync.</p></div><button class="soft-button" id="export-data">Export backup ↓</button></div><div class="setting-row"><div><h3>Sample activities</h3><p>Remove the starter activities when you’re ready to begin.</p></div><button class="soft-button" id="clear-samples">Remove samples</button></div><div class="setting-row"><div><h3>Calendar export</h3><p>Download your schedule as an .ics calendar with repeat rules.</p></div><button class="soft-button" id="export-calendar">Export calendar ↓</button></div><p class="form-hint" style="margin-top:22px">Monthly and yearly repeats use the last day of shorter months. Overlapping activities share the 24-hour budget: later-starting activities take precedence.</p></section>`}
function drawCharts(){if(typeof Chart==='undefined')return;Chart.defaults.font.family="'DM Sans', sans-serif";Chart.defaults.color='#98a18d';if($('#allocation')){let al=dayAllocation(selected);charts.push(new Chart($('#allocation'),{type:'doughnut',data:{labels:Object.keys(al),datasets:[{data:Object.values(al),backgroundColor:Object.keys(al).map(c=>cats[c]?.[2]||'#e7ebdf'),borderColor:'#fafbf8',borderWidth:5,borderRadius:7,hoverOffset:3}]},options:{responsive:true,maintainAspectRatio:false,cutout:'78%',plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>`${ctx.label}: ${hours(ctx.raw)}`}}}}}))}if($('#week-chart')){let ds=lastDays(7);charts.push(new Chart($('#week-chart'),{type:'bar',data:{labels:ds.map(d=>parseDate(d).toLocaleDateString(undefined,{weekday:'short'})),datasets:[{label:'Completed',data:ds.map(d=>events(d).filter(a=>state.done[a.key]).length),backgroundColor:'#8da27a',borderRadius:5,barThickness:17},{label:'Scheduled',data:ds.map(d=>events(d).length),backgroundColor:'#e4eadc',borderRadius:5,barThickness:17}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},border:{display:false},ticks:{font:{size:9}}},y:{beginAtZero:true,ticks:{stepSize:1,font:{size:9}},grid:{color:'#eef1e9'},border:{display:false}}}}}))}}
function render(){charts.forEach(c=>c.destroy());charts=[];$('#main').innerHTML=({dashboard,calendar,timetable,analytics,notifications,settings}[view]||dashboard)();$('#breadcrumb').textContent={dashboard:'Overview',calendar:'Calendar',timetable:'My timetable',analytics:'Insights & analytics',notifications:'Notification log',settings:'Preferences'}[view];$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#log-count').textContent=state.logs.length;drawCharts();}
function openForm(id,hour){const form=$('#activity-form');form.reset();$('#form-error').textContent='';let a=state.activities.find(a=>a.id===id);$('#modal-title').textContent=a?'Edit or reschedule':'Plan an activity';form.elements.id.value=a?.id||'';form.elements.date.value=a?.date||selected;form.elements.start.value=a?.start||`${String(hour??9).padStart(2,'0')}:00`;form.elements.end.value=a?.end||`${String(((hour??9)+1)%24).padStart(2,'0')}:00`;if(a)for(const k of ['title','category','repeat','link','notes'])form.elements[k].value=a[k]||'';$('#activity-dialog').showModal()}
$('#activity-form').addEventListener('submit',e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.title=data.title.trim();if(!data.title){$('#form-error').textContent='Please give your activity a name.';return}if(data.link&&!/^https?:\/\//i.test(data.link)){$('#form-error').textContent='Use a meeting link starting with https:// or http://.';return}let old=state.activities.find(a=>a.id===data.id);if(old){Object.assign(old,data);for(const key of Object.keys(state.done))if(key.startsWith(old.id+'@'))delete state.done[key];log('Rescheduled / edited',`${data.title}: ${data.date}, ${data.start}–${data.end}. Completion history for this series was reset.`)}else{data.id=crypto.randomUUID();state.activities.push(data);log('Activity added',`${data.title}: ${data.date}, ${data.start}–${data.end}`)}save();$('#activity-dialog').close();render();toast(old?'Activity updated. Repeat-series edits apply to all occurrences.':'A little intention added to your day.')});
$('#close-modal').onclick=()=>$('#activity-dialog').close();$('#dock-add').onclick=()=>openForm();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.view){view=d.view;render()}if('add'in d)openForm();if(d.edit)openForm(d.edit);if(d.hour)openForm(null,Number(d.hour));if(d.delete){let a=state.activities.find(a=>a.id===d.delete);if(confirm(`Delete “${a.title}”${a.repeat!=='none'?' and all its repeating occurrences':''}?`)){state.activities=state.activities.filter(x=>x.id!==a.id);Object.keys(state.done).filter(k=>k.startsWith(a.id+'@')).forEach(k=>delete state.done[k]);log('Activity deleted',a.title);render();toast('Activity removed.')}}if(d.filter){filter=d.filter;render()}if(d.shift){selected=addDays(selected,Number(d.shift));render()}if(d.day){selected=d.day;view='dashboard';render()}if(b.id==='today'){selected=today();render()}if(b.id==='prev-month'||b.id==='next-month'){calendarMonth.setDate(1);calendarMonth.setMonth(calendarMonth.getMonth()+(b.id==='prev-month'?-1:1));render()}if(b.id==='month-today'){calendarMonth=parseDate(today());render()}if(b.id==='enable-reminders'){if(state.reminders){state.reminders=false;log('Reminders disabled','Daily 8 PM browser reminders disabled.')}else if(!('Notification'in window)){toast('This browser does not support notifications.');log('Unsupported','Browser notification API unavailable.')}else{let p=await Notification.requestPermission();state.reminders=p==='granted';log(p==='granted'?'Reminders enabled':'Permission blocked',`Browser notification permission: ${p}.`);if(p==='granted')toast('8 PM reminders enabled while this planner is open.')}render()}if(b.id==='export-data')download('dayform-backup.json',JSON.stringify(state,null,2),'application/json');if(b.id==='export-log')download('dayform-audit.json',JSON.stringify(state.logs,null,2),'application/json');if(b.id==='clear-samples'){let count=state.activities.filter(a=>a.notes==='Sample activity — make this day your own.').length;state.activities=state.activities.filter(a=>a.notes!=='Sample activity — make this day your own.');state.seed=false;log('Samples removed',`${count} sample activities removed.`);render();toast('Ready for your own rhythm.')}if(b.id==='export-calendar')exportCalendar()});
document.addEventListener('change',e=>{if(e.target.id==='selected-date'&&e.target.value){selected=e.target.value;render()}if(e.target.dataset.complete){let key=e.target.dataset.complete,split=key.lastIndexOf('@'),a=events(key.slice(split+1)).find(a=>a.key===key);if(!a||Date.now()<a.begin){e.target.checked=false;toast('Completion unlocks at the activity’s start time.');return}if(e.target.checked)state.done[key]=new Date().toISOString();else delete state.done[key];log(e.target.checked?'Completed':'Completion undone',a.title+' · '+a.day);render()}});
function download(name,content,type){let url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCalendar(){const stamp=d=>dateKey(d).replaceAll('-','')+'T'+String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0')+'00',clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dayform//Planner//EN'];state.activities.forEach(a=>{let begin=new Date(a.date+'T'+a.start),finish=new Date(begin.getTime()+duration(a)*60000);lines.push('BEGIN:VEVENT','UID:'+a.id+'@dayform','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+stamp(begin),'DTEND:'+stamp(finish),'SUMMARY:'+clean(a.title),'DESCRIPTION:'+clean(a.notes||''));if(a.link)lines.push('URL:'+a.link);if(a.repeat!=='none')lines.push('RRULE:FREQ='+a.repeat.toUpperCase());lines.push('END:VEVENT')});lines.push('END:VCALENDAR');download('dayform-calendar.ics',lines.join('\r\n'),'text/calendar')}
function checkReminder(){if(!state.reminders)return;let now=new Date(),key=today(),last=state.lastReminder;if(last&&last<key){let yesterday=addDays(key,-1);if(last<yesterday)log('Missed reminder window','The planner was not open for one or more previous 8 PM reminder windows. No delivery is claimed.')}if(now.getHours()<20||last===key)return;state.lastReminder=key;let pending=events(key).filter(a=>!state.done[a.key]).length;if('Notification'in window&&Notification.permission==='granted'){try{new Notification('Your day, a little reflection.',{body:`You have ${pending} unchecked activities today. Review your day and make room for tomorrow.`,tag:'dayform-'+key});log('Notification requested',`8 PM daily check-in: ${pending} unchecked activities. Browser accepted the request; device delivery is not verifiable.`)}catch(err){log('Notification failed',err.message)}}else log('Notification blocked','Browser permission is unavailable. No notification sent.');save();if(view==='notifications')render()}
save();render();checkReminder();setInterval(()=>{checkReminder();if(!$('#activity-dialog').open&&['dashboard','timetable','analytics'].includes(view))render()},60000);
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){document.addEventListener('pointermove',e=>{let banner=document.querySelector('.balance-banner');if(banner&&e.pointerType==='mouse'){let r=banner.getBoundingClientRect();let within=e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom;banner.style.transform=within?`perspective(800px) rotateX(${(e.clientY-r.top-r.height/2)/40}deg) rotateY(${(e.clientX-r.left-r.width/2)/80}deg)`:'none'}})}
